// TicketFilter provides filtering for Ticket queries
type TicketFilter struct {
	Id                 *UUIDFilter
	Subject            *StringFilter
	Body               *StringFilter
	Category           *StringFilter
	Priority           *StringFilter
	ProvenanceInReview *BoolFilter
	Status             *StringFilter
	StatusEnteredAt    *DateTimeFilter
	Version            *Int64Filter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []TicketFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []TicketFilter
}

// TicketUpdate provides fields that can be updated
type TicketUpdate struct {
	Subject         *string
	Body            *string
	BodySetNull     bool
	Category        *types.Category
	CategorySetNull bool
	Priority        *string
	PrioritySetNull bool
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewTicketSnapshotUpdate maps every mutable field from a complete
// Ticket value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewTicketSnapshotUpdate(input *types.Ticket) *TicketUpdate {
	update := &TicketUpdate{}
	if input == nil {
		return update
	}
	update.Subject = &input.Subject
	var zeroBody string
	if input.Body == zeroBody {
		update.BodySetNull = true
	} else {
		update.Body = &input.Body
	}
	if input.Category == nil {
		update.CategorySetNull = true
	} else {
		update.Category = input.Category
	}
	var zeroPriority string
	if input.Priority == zeroPriority {
		update.PrioritySetNull = true
	} else {
		update.Priority = &input.Priority
	}
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *TicketUpdate) ApplyTo(row *types.Ticket) {
	if u == nil || row == nil {
		return
	}
	if u.Subject != nil {
		row.Subject = *u.Subject
	}
	if u.BodySetNull {
		var zeroBody string
		row.Body = zeroBody
	} else if u.Body != nil {
		row.Body = *u.Body
	}
	if u.CategorySetNull {
		row.Category = nil
	} else if u.Category != nil {
		row.Category = u.Category
	}
	if u.PrioritySetNull {
		var zeroPriority string
		row.Priority = zeroPriority
	} else if u.Priority != nil {
		row.Priority = *u.Priority
	}
}

// TicketFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func TicketFilterConditions(filter *TicketFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a TicketFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *TicketFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

